# engine/graph/builder.py

from .models.graph.graph import Graph
from .models.graph.node import Node
from .models.graph.edge import Edge
from .validation import validate_experiment, validate_graph


def build_graph(experiment, registry):
    """Build an executable graph from an experiment definition."""

    validate_experiment(experiment)

    nodes = []
    edges = []

    # Keeps track of the nodes generated by each block.
    block_nodes = {}

    # Blocks are processed respecting their dependencies.
    ordered_blocks = _order_blocks(experiment.blocks)

    for block in ordered_blocks:

        # Collect nodes produced by the blocks this block depends on.
        input_nodes = []

        for input_block_id in block.inputs:
            input_nodes.extend(block_nodes[input_block_id])

        generated_nodes = []

        for variant in block.variants:

            pipe = registry.get(variant.pipe)

            # The pipe decides how many concrete nodes should be created.
            specs = pipe.expand(
                input_nodes=input_nodes,
                params=variant.params
            )

            for index, spec in enumerate(specs):

                node_id = (
                    f"{block.id}."
                    f"{variant.id}."
                    f"{index}"
                )

                node = Node(
                    id=node_id,
                    block_id=block.id,
                    variant_id=variant.id,
                    pipe=variant.pipe,
                    params=spec.get("params", {})
                )

                nodes.append(node)
                generated_nodes.append(node)

                # Connections are defined by the expansion result.
                for source_id in spec.get("inputs", []):
                    edges.append(
                        Edge(
                            source=source_id,
                            target=node_id
                        )
                    )

        block_nodes[block.id] = generated_nodes

    graph = Graph(
        id=f"{experiment.id}_graph",
        experiment_id=experiment.id,
        nodes=nodes,
        edges=edges
    )

    validate_graph(graph)

    return graph


def _order_blocks(blocks):
    """Return blocks in dependency order."""

    block_map = {
        block.id: block
        for block in blocks
    }

    ordered = []
    visited = set()

    def visit(block):

        if block.id in visited:
            return

        for input_id in block.inputs:
            visit(block_map[input_id])

        visited.add(block.id)
        ordered.append(block)

    for block in blocks:
        visit(block)

    return ordered